def separer_adresses(apps, schema_editor):
    """« 1 rue X\n69000 Lyon » devient adresse « 1 rue X », code postal 69000, ville Lyon."""
    for p in apps.get_model("patrimoine", "Proprietaire").objects.exclude(adresse=""):
        lignes = [l.strip() for l in p.adresse.strip().splitlines() if l.strip()]
        m = re.match(r"^(.*?)[ ,]*\b(\d{5})\s+(.+)$", lignes[-1]) if lignes else None
        if m:
            reste = [m.group(1)] if m.group(1) else []
            p.adresse = "\n".join(lignes[:-1] + reste)
            p.code_postal, p.ville = m.group(2), m.group(3)
            p.save(update_fields=["adresse", "code_postal", "ville"])


